/** Rasterize SVG graphics generated by the editor, for formats requiring a PNG preview. */
export async function renderLocalSvg(
	doc: Document,
	svg: string,
	width: number,
	height: number,
): Promise<HTMLCanvasElement> {
	const image = doc.createElement('img');
	const url = URL.createObjectURL(new Blob([svg], { type: 'image/svg+xml' }));
	try {
		image.src = url;
		await image.decode();
		const canvas = doc.createElement('canvas');
		canvas.width = width;
		canvas.height = height;
		const context = canvas.getContext('2d');
		if (!context) throw new Error('Could not render the graphic.');
		context.drawImage(image, 0, 0, width, height);
		return canvas;
	} finally {
		URL.revokeObjectURL(url);
	}
}

export async function iconPngFile(
	doc: Document,
	icon: { name: string; svg: string },
): Promise<File> {
	const canvas = await renderLocalSvg(doc, icon.svg, 96, 96);
	const png = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/png'));
	if (!png) throw new Error('Could not render the icon.');
	return new File([png], `${icon.name}.png`, { type: png.type });
}
